async () => { /* C1 the collapsed-header set opens: two messages, header panel collapsed, on the brief */ const mg = window.MinigameFramework.currentMinigame; const s = mg.getTestState();
  return s.overlay.sceneType === 'inbox-triage' && s.triage.setId === 'slice_inbox_collapsed'
    && s.triage.headerPanel === 'collapsed' && s.triage.total === 2 && s.triage.step === 'brief'
    && s.overlay.layers.length === 0; }

async () => { /* C2 opening a message: the header panel is collapsed behind a Show-details toggle and is not yet an Esc layer */ const mg = window.MinigameFramework.currentMinigame;
  const start = mg.container.querySelector('.tri-start'); if (!start) return false; start.click();
  const row = mg.container.querySelector('.mail-row[data-id="col_phish"]'); if (!row) return false; row.click();
  const s = mg.getTestState();
  const toggle = mg.container.querySelector('.mail-details-toggle');
  return s.triage.selectedId === 'col_phish' && !!toggle && s.triage.detailsOpen === false
    && !mg.container.querySelector('.tri-header-panel')
    && !s.overlay.layers.includes('message-details') && s.overlay.layers.length === 0; }

async () => { /* C3 opening the header panel pushes it as the Esc layer, above the overlay */ const mg = window.MinigameFramework.currentMinigame;
  const toggle = mg.container.querySelector('.mail-details-toggle'); if (!toggle) return false; toggle.click();
  const s = mg.getTestState();
  return s.triage.detailsOpen === true && !!mg.container.querySelector('.tri-header-panel')
    && s.overlay.layers.includes('message-details') && /Authentication-Results/.test(mg.container.querySelector('.tri-header-panel').textContent); }

async () => { /* C4 Esc closes the header panel before the overlay: the panel is gone, the layer is popped, the round is still open and unanswered */ const t = window.__test; const mg = window.MinigameFramework.currentMinigame; const s = mg.getTestState();
  return s.triage.detailsOpen === false && !mg.container.querySelector('.tri-header-panel')
    && !s.overlay.layers.includes('message-details') && s.overlay.layers.length === 0
    && s.triage.step === 'sort' && s.triage.answered === 0
    && t.getState().activeMinigame && t.getState().activeMinigame.id === 'inbox-triage'; }
